(async()=>{const out={};for(const [key,values]of Object.entries({family:['A','A B','"A B"','serif','','A,B','123','A   B'],style:['italic','oblique 10deg','bad'],weight:['400','bold','100 900','0'],stretch:['condensed','75%','bad'],unicodeRange:['u+0-ff','U+4??','bad'],display:['swap','bad'],sizeAdjust:['120%','-1%'],featureSettings:['"liga" 0','bad']})){out[key]=values.map(value=>{const f=new FontFace('Base','local(Test)');f.loaded.catch(()=>{});let error=null;try{f[key]=value}catch(e){error=e.name}return[value,f[key],f.status,error]})}return out})()
